const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    // Define a large polygon encompassing the Great Lakes.
    const greatLakes = ee.Geometry.Polygon([[
        [-92.5, 41.5], [-92.5, 49.0], [-76.0, 49.0],
        [-76.0, 41.5], [-92.5, 41.5]
    ]]);

    // Define the specific date of interest.
    const startDate = '2016-02-11';
    const endDate = '2016-02-12';

    // 2. Data Acquisition & Check
    // Use MODIS Daily Surface Reflectance for its daily coverage and cloud state band.
    let collection = ee.ImageCollection('MODIS/061/MOD09GA')
        .filterDate(startDate, endDate)
        .filterBounds(greatLakes);

    const collectionSize = collection.size().getInfo();
    if (collectionSize === 0) {
        console.log("Evidence: No MODIS images found for the specified date and location.");
        console.log("A"); // Likely clouds present as no surface reflectance could be derived, which is a common reason for missing daily products.
        return;
    }

    // 3. Processing
    // Create a mosaic of all images for the day.
    const image = collection.mosaic().clip(greatLakes);

    // Function to extract cloud information from the 'state_1km' band.
    // Bits 0-1: Cloud State (00:clear, 01:cloudy, 10:mixed) -> GTE(1) means cloudy or mixed
    // Bits 8-9: Cirrus detected (00:none, 01:small, 10:average, 11:high) -> GT(0) means any cirrus
    const getCloudMask = function(img) {
        const state = img.select('state_1km');
        const cloudState = state.bitwiseAnd(3); // Extract bits 0-1
        const cirrusState = state.rightShift(8).bitwiseAnd(3); // Extract bits 8-9
        const cloudMask = cloudState.gte(1).or(cirrusState.gt(0));
        return cloudMask.rename('cloud');
    };

    const cloudImage = getCloudMask(image);

    // 4. Calculation
    const scale = 1000; // Use a coarse scale appropriate for MODIS 1km data and a large area.

    // Calculate the total number of pixels in the region.
    const totalPixelsStat = cloudImage.select('cloud').reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: greatLakes,
        scale: scale,
        maxPixels: 1e9
    });

    const totalPixels = ee.Number(totalPixelsStat.get('cloud')).getInfo();

    if (totalPixels === 0 || totalPixels === null) {
        console.log("Evidence: No valid pixels found in the Great Lakes region for analysis.");
        console.log("C2");
        return;
    }

    // Calculate the number of cloudy pixels.
    const cloudyPixelsStat = cloudImage.reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: greatLakes,
        scale: scale,
        maxPixels: 1e9
    });

    const cloudyPixels = ee.Number(cloudyPixelsStat.get('cloud')).getInfo();

    if (cloudyPixels === null) {
        console.log("Evidence: Cloud pixel calculation failed.");
        console.log("C3");
        return;
    }

    const cloudPercentage = (cloudyPixels / totalPixels) * 100;

    // 5. Validation & Final Answer
    console.log(`Date: ${startDate}`);
    console.log(`Image Count: ${collectionSize}`);
    console.log(`Total Pixels Analyzed: ${totalPixels}`);
    console.log(`Cloudy Pixels Found: ${cloudyPixels}`);
    console.log(`Cloud Cover Percentage: ${cloudPercentage.toFixed(2)}%`);

    if (cloudyPixels > 0) {
        console.log("A");
    } else {
        console.log("B");
    }
}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
}

initEE().catch(err => {
    console.error(err);
    console.log("D");
});
